    S.northMode = d && d.northMode || (d && Object.prototype.hasOwnProperty.call(d,'northDeg') ? BimNorth.modeOf(d.northDeg) : initialClimate && initialClimate.northMode || BimNorth.modeOf(S.northDeg));
