    st.north = null; st.T = null; st.location = []; st.aecLoc = null; st.purpose = null; st.group = null; st.lanDiag = []; st.categoryDiagnostics=null; st.locationWarning = ''; st.storageWarning = ''; st.level = null; st.plan = false; st.drawn = null;
