    const reasons = [...new Set(st.res.filter(r => r.kind === 'err').map(r => r.err))];
    if (reasons.length) return `КЕО не рассчитан. Причины: ${reasons.slice(0, 3).join('; ')}${reasons.length > 3 ? '; остальные — в разделе «Без расчёта»' : ''}`;
