        unresolvedRooms: st.normOv[sp.key] !== undefined ? [] : sp.rooms.filter(rm => st.normOv[rm.key] !== '-' && !normRow(rm) && !Cc.knownUnnormed(rm.name, st.group)).map(rm => `${rm.num} ${rm.name}`),
