    const scale=Math.min(300/(x1-x0),160/(y1-y0)),xy=p=>[10+(p[0]-x0)*scale,10+(y1-p[1])*scale],pair=p=>xy(p).join(',');
    const mask=qs.map(q=>`<polygon points="${[[q[0],q[2]],[q[1],q[2]],[q[1],q[3]],[q[0],q[3]]].map(pair).join(' ')}"/>`).join('');
